typedef int nvlMsg;

enum nvlMsgMode
{
  NVL_MSG_BLOCK,
  NVL_MSG_NOBLOCK
};

enum
{
  NVL_MSG_INVALID = -1
};

const int NVL_MAX_STREAM_NUM = 8;

struct nvlMsgQueue
{
  int sema;
  nvlMsg* array;
};

struct nvlStream
{
  int idx;
};

struct SemaParam
{
  int currentCount;
  char released_rest[28];
};

struct nvlStreamSystemData_t
{
  char released_to_pStream[140];
  nvlStream* pStream[NVL_MAX_STREAM_NUM];
};

extern nvlStreamSystemData_t nvlStreamSystemData;
extern "C" int WaitSema(int);
extern "C" int PollSema(int);
extern "C" int ReferSemaStatus(int, SemaParam*);
extern "C" void __assert(const char*, int, const char*);

static nvlMsg nvlReceiveMsg( nvlMsgQueue* q, nvlMsgMode mode, nvlStream** s )
{
  nvlMsg  rv = NVL_MSG_INVALID;
  int     res;

  if (!( q && s )) __assert("C:/NVL/ps2/nvlstream_ps2.cpp", 161, "q && s");
  if( mode == NVL_MSG_BLOCK )
  {
    res = WaitSema( q->sema );
  }
  else
  {
    res = PollSema( q->sema );
  }
  if (!( !(mode == NVL_MSG_BLOCK && res != q->sema) )) __assert("C:/NVL/ps2/nvlstream_ps2.cpp", 170, "!(mode == NVL_MSG_BLOCK && res != q->sema)");
  if( res == q->sema )
  {
    struct SemaParam  semaParam;

    res = ReferSemaStatus( q->sema, &semaParam );
    if (!( res == q->sema && semaParam.currentCount >= 0 )) __assert("C:/NVL/ps2/nvlstream_ps2.cpp", 176, "res == q->sema && semaParam.currentCount >= 0");
    rv = q->array[semaParam.currentCount];
    res = rv >> 16;
    if (!( res >= -1 && res < NVL_MAX_STREAM_NUM )) __assert("C:/NVL/ps2/nvlstream_ps2.cpp", 179, "res >= -1 && res < NVL_MAX_STREAM_NUM");
    *s = ( res >= 0 )? nvlStreamSystemData.pStream[res] : 0;
    if (!( *s == 0 || (*s)->idx == res )) __assert("C:/NVL/ps2/nvlstream_ps2.cpp", 181, "*s == NULL || (*s)->idx == res");
    rv &= 0xffff;
  }
  return rv;
}
